WITH cleaned AS (SELECT id, order_id, method, amount, status, SUBSTRING(method, 1, 3) AS method_prefix FROM payments WHERE order_id IS NOT NULL AND TO_DATE(paid_at) < '2023-10-01') SELECT id, order_id, method, amount, status, method_prefix, ROUND(amount / SUM(amount) OVER (PARTITION BY method), 4) AS amount_share, LAST_VALUE(amount) IGNORE NULLS OVER (ORDER BY amount ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_amount FROM cleaned
